        },
        {
          "line": 8,
          "text": "export function processEntity(rawBytes: Uint8Array, version: string) {"
        },
        {
          "line": 9,
          "text": "  if (version !== \"v1\" && version !== \"v2\") throw new Error(`Unsupported schema version: ${version}`);"
        },
