        },
        {
          "line": 17,
          "text": "  const chunks: Buffer[] = [];"
        },
        {
          "line": 18,
          "text": "  for await (const chunk of request) chunks.push(Buffer.from(chunk));"
        },
        {
          "line": 19,
          "text": "  return Buffer.concat(chunks);"
        },
        {
          "line": 20,
          "text": "}"
        },
        {
          "line": 21,
          "text": ""
        },
        {
          "line": 22,
          "text": "if (process.argv.includes(\"--serve\")) {"
        },
        {
          "line": 23,
          "text": "  createServer(async (request, response) => {"
        },
        {
          "line": 24,
          "text": "    if (request.method === \"GET\" && request.url === \"/health\") {"
        },
        {
          "line": 25,
          "text": "      response.writeHead(200, { \"content-type\": \"application/json\" });"
        },
        {
          "line": 26,
          "text": "      response.end(JSON.stringify({ status: \"ok\", runtime: \"typescript\" }));"
        },
        {
          "line": 27,
          "text": "      return;"
        },
        {
          "line": 28,
          "text": "    }"
        },
        {
          "line": 29,
          "text": "    if (request.method !== \"POST\" || request.url !== \"/relay\") {"
        },
        {
          "line": 30,
          "text": "      response.writeHead(404); response.end(); return;"
        },
        {
          "line": 31,
          "text": "    }"
        },
        {
          "line": 32,
          "text": "    try {"
