          "line": 33,
          "text": "      const { entity, fields } = processEntity(await readBody(request), \"v1\");"
        },
        {
          "line": 34,
          "text": "      const trace = JSON.parse(String(request.headers[traceHeader.toLowerCase()] ?? \"[]\"));"
        },
        {
          "line": 35,
          "text": "      trace.push(\"typescript\");"
        },
        {
          "line": 36,
          "text": "      const downstream = await fetch(process.env.CSHARP_RELAY_URL ?? \"http://localhost:8002/relay\", {"
        },
        {
          "line": 37,
          "text": "        method: \"POST\","
        },
        {
          "line": 38,
          "text": "        headers: { \"content-type\": \"application/x-protobuf\", [traceHeader]: JSON.stringify(trace) },"
        },
        {
          "line": 39,
          "text": "        body: Buffer.from(EntityV1.encode(entity as EntityV1).finish()),"
        },
        {
          "line": 40,
          "text": "        signal: AbortSignal.timeout(5000),"
        },
