          "line": 41,
          "text": "      });"
        },
        {
          "line": 42,
          "text": "      if (!downstream.ok) throw new Error(`C# relay returned ${downstream.status}`);"
        },
        {
          "line": 43,
          "text": "      const body = Buffer.from(await downstream.arrayBuffer());"
        },
        {
          "line": 44,
          "text": "      const observations = [{ runtime: \"typescript\", fields }, ...JSON.parse(downstream.headers.get(observationsHeader) ?? \"null\")];"
        },
        {
          "line": 45,
          "text": "      response.writeHead(200, {"
        },
        {
          "line": 46,
          "text": "        \"content-type\": \"application/x-protobuf\", \"content-length\": body.length,"
        },
        {
          "line": 47,
          "text": "        [observationsHeader]: JSON.stringify(observations).replace(/[\\u007f-\\uffff]/g, c => `\\\\u${c.charCodeAt(0).toString(16).padStart(4, \"0\")}`),"
        },
        {
          "line": 48,
          "text": "        [traceHeader]: downstream.headers.get(traceHeader) ?? \"[]\","
        },
        {
          "line": 49,
          "text": "      });"
        },
        {
          "line": 50,
          "text": "      response.end(body);"
        },
        {
          "line": 51,
          "text": "    } catch (error) {"
        },
        {
          "line": 52,
          "text": "      response.writeHead(400, { \"content-type\": \"application/json\" });"
        },
        {
          "line": 53,
          "text": "      response.end(JSON.stringify({ error: String(error) }));"
        },
        {
          "line": 54,
          "text": "    }"
        },
        {
          "line": 55,
          "text": "  }).listen(Number(process.env.PORT ?? \"8001\"), \"0.0.0.0\");"
        },
        {
          "line": 56,
          "text": "} else {"
        },
        {
          "line": 57,
          "text": "  const version = process.argv.includes(\"--v2\") ? \"v2\" : \"v1\";"
        },
        {
          "line": 58,
          "text": "  const bytes = version === \"v1\""
        },
        {
          "line": 59,
          "text": "    ? EntityV1.encode({ entityId: \"ts_303\", name: \"Sensor C\" }).finish()"
        },
        {
          "line": 60,
          "text": "    : EntityV2.encode({ entityId: \"ts_303\" }).finish();"
        },
